using ghidra.util.task;

public class TutorialDebuggerMaintenance : AbstractGhidraHeadedIntegrationTest {
	public static readonly TaskMonitor CONSOLE = new ConsoleTaskMonitor();

	public PluginTool tool;
	public TestEnv env;
	public Program program;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();

		tool = env.launchDefaultTool();
	}

	/* @After */
	public void tearDown()
    {
		if (program != null) {
			program.release(this);
			program = null;
		}
	}

	/* @Test */
	public void testRecreateTermminesGzf()
    {
		File termmines = Application.getModuleDataFile("TestResources", "termmines").getFile(false);
		using (LoadResults<Program> loadResults = ProgramLoader.builder()
				.source(termmines)
				.project(env.getProject())
				.monitor(CONSOLE)
				.load())
{
			program = loadResults.getPrimaryDomainObject(this);
			try (Transaction tx = program.openTransaction("Analyze")) {
				program.setExecutablePath("/tmp/termmines");
				GhidraProject.analyze(program);
			}
			File dest = new File(termmines.getParentFile(), "termmines.gzf");
			dest.delete();
			program.saveToPackedFile(dest, CONSOLE);
		}
	}
}
